namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public int Id { get; set; }
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();
    private int _nextEnrollmentId = 1;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Code = "CS101", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She previously worked at Google and holds a PhD from MIT.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Code = "CS201", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Covers algorithm design and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM-12:00 PM", InstructorName = "Dr. James Wilson", InstructorBio = "Dr. Wilson specializes in algorithm optimization and has published over 30 papers in top conferences.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, Title = "Web Development", Code = "CS301", Description = "Full-stack web development covering HTML, CSS, JavaScript, and modern frameworks. Includes server-side programming and databases.", Credits = 3, Schedule = "Mon/Wed 2:00-3:30 PM", InstructorName = "Prof. Maria Garcia", InstructorBio = "Prof. Garcia is a full-stack developer with industry experience at Microsoft and Amazon. She focuses on modern web technologies.", IsFeatured = true },
            new() { Id = 4, DepartmentId = 1, Title = "Artificial Intelligence", Code = "CS401", Description = "Introduction to AI concepts including machine learning, neural networks, natural language processing, and computer vision.", Credits = 4, Schedule = "Tue/Thu 1:00-2:30 PM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park leads the university AI research lab and has contributed to several open-source ML frameworks.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, Title = "Calculus I", Code = "MATH101", Description = "Introduction to differential calculus covering limits, derivatives, and their applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor has been teaching calculus for over 20 years and authored two popular textbooks.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 2, Title = "Linear Algebra", Code = "MATH201", Description = "Study of vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00-10:30 AM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research focuses on applied linear algebra and numerical methods.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, Title = "Probability and Statistics", Code = "MATH301", Description = "Fundamentals of probability theory, statistical inference, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM-12:30 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown works in applied statistics and has consulted for several Fortune 500 companies.", IsFeatured = false },

            // Physics
            new() { Id = 8, DepartmentId = 3, Title = "Physics I: Mechanics", Code = "PHYS101", Description = "Classical mechanics covering kinematics, Newton's laws, energy, momentum, and rotational motion.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", InstructorName = "Dr. Lisa Johnson", InstructorBio = "Dr. Johnson is an award-winning physics educator with research in experimental particle physics.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, Title = "Electromagnetism", Code = "PHYS201", Description = "Study of electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 2:00-3:30 PM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim specializes in condensed matter physics and has received multiple NSF grants.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 3, Title = "Quantum Mechanics", Code = "PHYS301", Description = "Introduction to quantum theory including wave-particle duality, Schrödinger equation, and quantum states.", Credits = 4, Schedule = "Mon/Wed 3:00-4:30 PM", InstructorName = "Dr. Rachel Adams", InstructorBio = "Dr. Adams is a theoretical physicist whose work on quantum computing has been featured in Nature.", IsFeatured = true },

            // English
            new() { Id = 11, DepartmentId = 4, Title = "English Composition", Code = "ENG101", Description = "Develop effective writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", InstructorName = "Prof. Thomas Wright", InstructorBio = "Prof. Wright is a published author and has taught writing workshops across the country.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 4, Title = "American Literature", Code = "ENG201", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:30 PM", InstructorName = "Dr. Karen Mitchell", InstructorBio = "Dr. Mitchell specializes in 20th-century American fiction and has published extensively on Toni Morrison.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 4, Title = "Creative Writing", Code = "ENG301", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "Wed 6:00-9:00 PM", InstructorName = "Prof. Diana Lee", InstructorBio = "Prof. Lee is an award-winning novelist and poet with three published books.", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return _courses;

        var lowerQuery = query.ToLower();
        return _courses.Where(c =>
            c.Title.ToLower().Contains(lowerQuery) ||
            c.Code.ToLower().Contains(lowerQuery) ||
            c.Description.ToLower().Contains(lowerQuery) ||
            c.InstructorName.ToLower().Contains(lowerQuery)
        ).ToList();
    }

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _nextEnrollmentId++;
        request.SubmittedAt = DateTime.UtcNow;
        _enrollmentRequests.Add(request);
    }
}

