@page "/courses"
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Courses</PageTitle>

<h1>Course Catalog</h1>

<div class="search-filters">
    <input type="text" @bind="searchQuery" @bind:event="oninput" placeholder="Search courses..." class="search-input" />
    <select @bind="selectedDepartmentId" class="filter-select">
        <option value="0">All Departments</option>
        @foreach (var dept in departments)
        {
            <option value="@dept.Id">@dept.Name</option>
        }
    </select>
</div>

<table class="course-table">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th>Instructor</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in filteredCourses)
        {
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@course.Credits</td>
                <td>@course.Schedule</td>
                <td>@course.InstructorName</td>
                <td><a href="/courses/@course.Id">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (!filteredCourses.Any())
{
    <p class="no-results">No courses found matching your criteria.</p>
}

@code {
    private List<Department> departments = new();
    private string searchQuery = string.Empty;
    private int selectedDepartmentId;

    private List<Course> filteredCourses => GetFilteredCourses();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
    }

    private List<Course> GetFilteredCourses()
    {
        var courses = string.IsNullOrWhiteSpace(searchQuery)
            ? CatalogService.GetCourses()
            : CatalogService.SearchCourses(searchQuery);

        if (selectedDepartmentId > 0)
            courses = courses.Where(c => c.DepartmentId == selectedDepartmentId).ToList();

        return courses;
    }
}

@page "/courses/{Id:int}"
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Detail")</PageTitle>

@if (course is null)
{
    <p>Course not found.</p>
}
else
{
    <div class="course-detail">
        <a href="/courses" class="back-link">← Back to Courses</a>

        <h1>@course.Title</h1>
        <span class="course-code-badge">@course.Code</span>

        <div class="detail-grid">
            <div class="detail-section">
                <h3>Description</h3>
                <p>@course.Description</p>
            </div>

            <div class="detail-section">
                <h3>Details</h3>
                <dl>
                    <dt>Credits</dt>
                    <dd>@course.Credits</dd>
                    <dt>Schedule</dt>
                    <dd>@course.Schedule</dd>
                </dl>
            </div>

            <div class="detail-section">
                <h3>Instructor</h3>
                <p><strong>@course.InstructorName</strong></p>
                <p>@course.InstructorBio</p>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

