<PageTitle>Enroll</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>✓ Enrollment Request Submitted</h2>
        <p>Thank you, <strong>@model.StudentName</strong>! Your enrollment request has been received.</p>
        <a href="/enroll" @onclick="Reset" @onclick:preventDefault>Submit another request</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <div class="form-group">
            <label for="studentName">Student Name</label>
            <InputText id="studentName" @bind-Value="model.StudentName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="model.StudentId" class="form-control" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="model.CourseId" class="form-control">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
        </div>

        <button type="submit" class="btn-submit">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    private EnrollmentRequest model = new();
    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(model);
        submitted = true;
    }

    private void Reset()
    {
        model = new EnrollmentRequest();
        submitted = false;
    }
}

